"use strict";(self.webpackChunkfrank_quant=self.webpackChunkfrank_quant||[]).push([[2455],{4470:t=>{t.exports=JSON.parse('{"permalink":"/blog/Powering the AI Era","editUrl":"https://github.com/frank-quant/frank-quant/tree/main/blog/LLM\u5e94\u7528/2025-10-04-\u9ad8\u76db2025\u5e74AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b.md","source":"@site/blog/LLM\u5e94\u7528/2025-10-04-\u9ad8\u76db2025\u5e74AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b.md","title":"\u9ad8\u76db2025\u5e74AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b","description":"\u9ad8\u76db\u6700\u8fd1\u53d1\u4e862025 AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b\uff0c\u975e\u5e38\u6709\u53c2\u8003\u4ef7\u503c\u3002\u63d0\u70bc\u603b\u7ed3\u4e00\u4e0b\uff0c\u53ef\u4ee5\u5206\u4e3a19\u70b9\uff1a 1. AI\u662f\u57fa\u7840\u8bbe\u65bd\u9769\u547d\uff1aAI\u662f\u7ee7\u94c1\u8def\u3001\u7535\u6c14\u5316\u3001\u4e92\u8054\u7f51\u540e\u7684\u91cd\u5927\u6280\u672f\u62d0\u70b9\uff0c\u5176\u53d1\u5c55\u4f9d\u8d56\u8d44\u672c\u4e0e\u57fa\u7840\u8bbe\u65bd\u652f\u6491\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u4ee3\u7801\u4e0e\u6a21\u578b\u3002 2. \u5929\u4ef7\u6210\u672c\u7ed3\u6784\uff1a\u4e00\u5ea7250MW AI\u6570\u636e\u4e2d\u5fc3\u603b\u6210\u672c\u7ea6120\u4ebf\u7f8e\u5143\uff0c\u5176\u4e2d\u5185\u90e8GPU\u7b49\u8bbe\u5907\u6210\u672c\u662f\u7269\u7406\u5efa\u7b51\u6210\u672c\u76843-4\u500d\u3002 3. \u6700\u7d27\u8feb\u74f6\u9888\u5728\u7535\u529b\uff1a\u52302030\u5e74\uff0c\u5168\u7403\u6570\u636e\u4e2d\u5fc3\u7535\u529b\u9700\u6c42\u9884\u8ba1\u6fc0\u589e160%\uff0c\u4f46\u5f53\u524d\u8001\u65e7\u7535\u7f51\u65e0\u6cd5\u9002\u914d\uff0c\u6784\u6210\u6700\u7d27\u8feb\u74f6\u9888\u3002 4. \u77ed\u671f\u7535\u529b\u77db\u76fe\u7a81\u51fa\uff1a\u5929\u7136\u6c14\u7535\u5382\u5ba1\u6279\u5efa\u8bbe\u97005-7\u5e74\uff0c\u98ce\u5149\u80fd\u6e90\u4f9b\u7535\u95f4\u6b47\u6027\u5f3a\uff0c\u6838\u7535\u662f\u957f\u671f\u65b9\u6848\uff0c\u5bfc\u81f4\u77ed\u671f\u7535\u529b\u4f9b\u9700\u77db\u76fe\u5c16\u9510\u3002 5. \u529f\u8017\u5bc6\u5ea6\u98d9\u5347\uff1a2027\u5e74AI\u670d\u52a1\u5668\u673a\u67b6\u529f\u7387\u5c06\u662f5\u5e74\u524d\u4e91\u670d\u52a1\u5668\u768450\u500d\uff0cGPU\u9ad8\u80fd\u8017\u4e9f\u9700\u6db2\u51b7\u7b49\u5148\u8fdb\u6563\u70ed\u65b9\u6848\u3002 6. \u8d44\u672c\u6295\u5165\u521b\u7eaa\u5f55\uff1a\u8d85\u5927\u89c4\u6a21\u4f01\u4e1a\uff08\u5982\u4e9a\u9a6c\u900a\u3001\u8c37\u6b4c\uff09\u8ba1\u52122027\u5e74\u6295\u51651\u4e07\u4ebf\u7f8e\u5143\u7528\u4e8eAI\uff0c2024\u5e74\u5168\u7403\u8be5\u7c7b\u4f01\u4e1a\u65e5\u8d44\u672c\u652f\u51fa\u7ea68\u4ebf\u7f8e\u5143\u3002 7. \u4f9b\u9700\u4e25\u91cd\u5931\u8861\uff1a\u5168\u7403\u6570\u636e\u4e2d\u5fc3\u7a7a\u7f6e\u7387\u4ec53%\uff0c\u70ed\u95e8\u5e02\u573a\u8fd10%\uff0c2028\u5e74\u524d\u96be\u6709\u5927\u89c4\u6a21\u65b0\u589e\u7535\u529b\uff0c\u4f9b\u9700\u7f3a\u53e3\u663e\u8457\u3002 8. \u878d\u8d44\u6a21\u5f0f\u521b\u65b0\uff1a\u4f20\u7edf\u878d\u8d44\u5931\u6548\uff0c\u9700VC\u3001SASB\u8bc1\u5238\u5316\u7b49\u521b\u65b0\u65b9\u5f0f\u30022025\u5e74\u6570\u636e\u4e2d\u5fc3SASB\u4ea4\u6613\u89c4\u6a21\u9884\u8ba1\u7a81\u783420\u4ebf\u7f8e\u5143\u3002 9. \u4e3b\u6743\u57fa\u91d1\u5165\u573a\uff1a2024\u5e74Equinix\u8054\u5408\u65b0\u52a0\u5761\u4e3b\u6743\u57fa\u91d1\u3001\u52a0\u62ff\u5927\u517b\u8001\u91d1\u52df\u8d44150\u4ebf\u7f8e\u5143\uff0c\u7528\u4e8e\u6269\u5efa\u7f8e\u56fd\u8d85\u5927\u89c4\u6a21\u6570\u636e\u4e2d\u5fc3\u3002 10. \u7535\u7f51\u8001\u5316\u4e25\u91cd\uff1a\u7f8e\u56fd\u7535\u7f51\u8bbe\u65bd\u5e73\u5747\u5df2\u4f7f\u752840\u5e74\uff0c2030\u5e74\u7f8e\u56fd\u6570\u636e\u4e2d\u5fc3\u9700\u6c42\u4e0e\u4f9b\u5e94\u7f3a\u53e3\u5c06\u8fbe10.4GW\u3002 11. \u80fd\u6e90\u7ed3\u6784\u9884\u6d4b\uff1a\u9ad8\u76db\u9884\u6d4b\uff0c60%\u6570\u636e\u4e2d\u5fc3\u65b0\u589e\u7535\u529b\u9700\u6c42\u5c06\u753130%\u5929\u7136\u6c14CCGT\u300130%\u5929\u7136\u6c14\u8c03\u5cf0\u7535\u5382\u300127.5%\u592a\u9633\u80fd\u300112.5%\u98ce\u80fd\u6ee1\u8db3\u3002 12. \u6838\u7535\u76ee\u6807\u8fdc\u5927\uff1a\u7f8e\u56fd\u653f\u5e9c\u63a8\u52a82050\u5e74\u6838\u7535\u5bb9\u91cf\u8fbe400GW\uff08\u5f53\u524d100GW\uff09\uff0c\u5fae\u8f6f\u7b49\u4f01\u4e1a\u901a\u8fc7\u957f\u671f\u8d2d\u7535\u534f\u8bae\u91cd\u542f\u65e7\u6838\u7535\u7ad9\u3002 13. \u8868\u540e\u4f9b\u7535\u5174\u8d77\uff1a\u201c\u81ea\u5efa\u5fae\u7535\u7f51\u3001\u76f4\u8fde\u7535\u5382\u201d\u6210\u4e3a\u7ed5\u5f00\u7535\u7f51\u74f6\u9888\u7684\u9009\u62e9\uff0c\u4f46\u5b58\u5728\u6c61\u67d3\u4e0e\u76d1\u7ba1\u4e89\u8bae\u3002 14. \u5168\u7403\u8d44\u672c\u9700\u6c42\uff1a\u52302030\u5e74\uff0c\u5168\u7403\u80fd\u6e90\u8f6c\u578b\u3001\u7535\u529b\u4e0e\u516c\u7528\u4e8b\u4e1a\u3001\u6570\u5b57\u57fa\u7840\u8bbe\u65bd\u5206\u522b\u970012\u4e07\u4ebf\u30013\u4e07\u4ebf\u30012\u4e07\u4ebf\u7f8e\u5143\u8d44\u672c\u3002 15. \u65b0\u52a0\u5761REIT\u4f18\u52bf\uff1a\u65b0\u52a0\u5761REIT\u5e02\u573a\uff08\u89c4\u6a21680\u4ebf\u7f8e\u5143\uff09\u56e0\u7a0e\u6536\u4f18\u52bf\uff0c\u6210\u4e3a\u5168\u7403\u6570\u636e\u4e2d\u5fc3REIT\u4e0a\u5e02\u70ed\u95e8\u9009\u62e9\u3002 16. \u65b0\u73a9\u5bb6\u6d8c\u5165\uff1a\u9664\u8d85\u5927\u89c4\u6a21\u4f01\u4e1a\u5916\uff0c\u65b0\u5174\u4e91\u5382\u5546\u4e5f\u5728\u65a5\u8d44\u5efa\u8bbeGPU\u6570\u636e\u4e2d\u5fc3\uff0c\u52a0\u5267\u5e02\u573a\u7ade\u4e89\u3002 17. AI\u63a8\u7406\u8017\u7535\u5de8\u5927\uff1a\u4e00\u6b21ChatGPT\u67e5\u8be2\u7684\u8017\u7535\u91cf\u7ea6\u4e3a\u4e00\u6b21Google\u641c\u7d22\u768410\u500d\uff0c\u51f8\u663eAI\u5e94\u7528\u80fd\u6548\u5dee\u5f02\u3002 18. \u94dc\u6210\u4e3a\u6218\u7565\u8d44\u6e90\uff1a\u7535\u7f51\u5927\u89c4\u6a21\u5347\u7ea7\u5c06\u63a8\u52a8\u94dc\u9700\u6c42\uff0c\u52302030\u5e74\uff0c\u7535\u7f51\u5efa\u8bbe\u5c06\u8d21\u732e\u5168\u7403\u94dc\u9700\u6c42\u589e\u957f\u768460%\u3002 19. \u5730\u7f18\u653f\u6cbb\u5de5\u5177\u5316\uff1a\u6570\u636e\u4e2d\u5fc3\u9009\u5740\u5df2\u6210\u4e3a\u5730\u7f18\u653f\u6cbb\u5de5\u5177\uff0c\u5404\u56fd\u901a\u8fc7\u653f\u7b56\u5438\u5f15\u6295\u8d44\uff0c\u62a5\u544a\u6307\u51fa\u4e2d\u56fd\u5728\u7535\u529b\u4f9b\u5e94\u65b9\u9762\u5177\u5907\u4f18\u52bf\u3002","date":"2025-10-04T00:00:00.000Z","tags":[{"inline":false,"label":"LLM\u5e94\u7528","permalink":"/blog/tags/tags/LLM\u5e94\u7528","description":"\u5927\u8bed\u8a00\u6a21\u578b\u5728\u91cf\u5316\u4ea4\u6613\u4e2d\u7684\u5e94\u7528"}],"readingTime":2.82,"hasTruncateMarker":false,"authors":[{"name":"Frank Quant","title":"\u91cf\u5316\u4ea4\u6613\u7814\u7a76\u5458","url":"https://github.com/frank-quant","page":{"permalink":"/blog/authors/frank"},"socials":{"github":"https://github.com/frank-quant","x":"https://x.com/frank_quant","linkedin":"https://www.linkedin.com/in/frank-quant/"},"imageURL":"https://github.com/frank-quant.png","key":"frank"}],"frontMatter":{"slug":"Powering the AI Era","title":"\u9ad8\u76db2025\u5e74AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b","authors":["frank"],"tags":["LLM\u5e94\u7528"]},"unlisted":false,"prevItem":{"title":"Cursor\u65b0\u5458\u5de5\u90fd\u8981\u7528Cursor\u5b8c\u6210\u4e00\u4e2a\u5165\u804c\u9879\u76ee","permalink":"/blog/Cursor_project_for_newer"},"nextItem":{"title":"\u6211\u60f3\u7ed9\u8ba1\u7b97\u673a\u4e13\u4e1a\u7684\u5927\u4e00\u65b0\u751f\u51e0\u4e2a\u5efa\u8bae","permalink":"/blog/some_advice"}}')},28453:(t,e,n)=>{n.d(e,{R:()=>i,x:()=>s});var r=n(96540);const a={},o=r.createContext(a);function i(t){const e=r.useContext(o);return r.useMemo(function(){return"function"==typeof t?t(e):{...e,...t}},[e,t])}function s(t){let e;return e=t.disableParentContext?"function"==typeof t.components?t.components(a):t.components||a:i(t.components),r.createElement(o.Provider,{value:e},t.children)}},54378:(t,e,n)=>{n.r(e),n.d(e,{assets:()=>u,contentTitle:()=>s,default:()=>I,frontMatter:()=>i,metadata:()=>r,toc:()=>l});var r=n(4470),a=n(74848),o=n(28453);const i={slug:"Powering the AI Era",title:"\u9ad8\u76db2025\u5e74AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b",authors:["frank"],tags:["LLM\u5e94\u7528"]},s=void 0,u={authorsImageUrls:[void 0]},l=[];function c(t){const e={p:"p",...(0,o.R)(),...t.components};return(0,a.jsx)(e.p,{children:"\u9ad8\u76db\u6700\u8fd1\u53d1\u4e862025 AI\u4ea7\u4e1a\u7814\u62a5\u300aPowering the AI Era\u300b\uff0c\u975e\u5e38\u6709\u53c2\u8003\u4ef7\u503c\u3002\u63d0\u70bc\u603b\u7ed3\u4e00\u4e0b\uff0c\u53ef\u4ee5\u5206\u4e3a19\u70b9\uff1a 1. AI\u662f\u57fa\u7840\u8bbe\u65bd\u9769\u547d\uff1aAI\u662f\u7ee7\u94c1\u8def\u3001\u7535\u6c14\u5316\u3001\u4e92\u8054\u7f51\u540e\u7684\u91cd\u5927\u6280\u672f\u62d0\u70b9\uff0c\u5176\u53d1\u5c55\u4f9d\u8d56\u8d44\u672c\u4e0e\u57fa\u7840\u8bbe\u65bd\u652f\u6491\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u4ee3\u7801\u4e0e\u6a21\u578b\u3002 2. \u5929\u4ef7\u6210\u672c\u7ed3\u6784\uff1a\u4e00\u5ea7250MW AI\u6570\u636e\u4e2d\u5fc3\u603b\u6210\u672c\u7ea6120\u4ebf\u7f8e\u5143\uff0c\u5176\u4e2d\u5185\u90e8GPU\u7b49\u8bbe\u5907\u6210\u672c\u662f\u7269\u7406\u5efa\u7b51\u6210\u672c\u76843-4\u500d\u3002 3. \u6700\u7d27\u8feb\u74f6\u9888\u5728\u7535\u529b\uff1a\u52302030\u5e74\uff0c\u5168\u7403\u6570\u636e\u4e2d\u5fc3\u7535\u529b\u9700\u6c42\u9884\u8ba1\u6fc0\u589e160%\uff0c\u4f46\u5f53\u524d\u8001\u65e7\u7535\u7f51\u65e0\u6cd5\u9002\u914d\uff0c\u6784\u6210\u6700\u7d27\u8feb\u74f6\u9888\u3002 4. \u77ed\u671f\u7535\u529b\u77db\u76fe\u7a81\u51fa\uff1a\u5929\u7136\u6c14\u7535\u5382\u5ba1\u6279\u5efa\u8bbe\u97005-7\u5e74\uff0c\u98ce\u5149\u80fd\u6e90\u4f9b\u7535\u95f4\u6b47\u6027\u5f3a\uff0c\u6838\u7535\u662f\u957f\u671f\u65b9\u6848\uff0c\u5bfc\u81f4\u77ed\u671f\u7535\u529b\u4f9b\u9700\u77db\u76fe\u5c16\u9510\u3002 5. \u529f\u8017\u5bc6\u5ea6\u98d9\u5347\uff1a2027\u5e74AI\u670d\u52a1\u5668\u673a\u67b6\u529f\u7387\u5c06\u662f5\u5e74\u524d\u4e91\u670d\u52a1\u5668\u768450\u500d\uff0cGPU\u9ad8\u80fd\u8017\u4e9f\u9700\u6db2\u51b7\u7b49\u5148\u8fdb\u6563\u70ed\u65b9\u6848\u3002 6. \u8d44\u672c\u6295\u5165\u521b\u7eaa\u5f55\uff1a\u8d85\u5927\u89c4\u6a21\u4f01\u4e1a\uff08\u5982\u4e9a\u9a6c\u900a\u3001\u8c37\u6b4c\uff09\u8ba1\u52122027\u5e74\u6295\u51651\u4e07\u4ebf\u7f8e\u5143\u7528\u4e8eAI\uff0c2024\u5e74\u5168\u7403\u8be5\u7c7b\u4f01\u4e1a\u65e5\u8d44\u672c\u652f\u51fa\u7ea68\u4ebf\u7f8e\u5143\u3002 7. \u4f9b\u9700\u4e25\u91cd\u5931\u8861\uff1a\u5168\u7403\u6570\u636e\u4e2d\u5fc3\u7a7a\u7f6e\u7387\u4ec53%\uff0c\u70ed\u95e8\u5e02\u573a\u8fd10%\uff0c2028\u5e74\u524d\u96be\u6709\u5927\u89c4\u6a21\u65b0\u589e\u7535\u529b\uff0c\u4f9b\u9700\u7f3a\u53e3\u663e\u8457\u3002 8. \u878d\u8d44\u6a21\u5f0f\u521b\u65b0\uff1a\u4f20\u7edf\u878d\u8d44\u5931\u6548\uff0c\u9700VC\u3001SASB\u8bc1\u5238\u5316\u7b49\u521b\u65b0\u65b9\u5f0f\u30022025\u5e74\u6570\u636e\u4e2d\u5fc3SASB\u4ea4\u6613\u89c4\u6a21\u9884\u8ba1\u7a81\u783420\u4ebf\u7f8e\u5143\u3002 9. \u4e3b\u6743\u57fa\u91d1\u5165\u573a\uff1a2024\u5e74Equinix\u8054\u5408\u65b0\u52a0\u5761\u4e3b\u6743\u57fa\u91d1\u3001\u52a0\u62ff\u5927\u517b\u8001\u91d1\u52df\u8d44150\u4ebf\u7f8e\u5143\uff0c\u7528\u4e8e\u6269\u5efa\u7f8e\u56fd\u8d85\u5927\u89c4\u6a21\u6570\u636e\u4e2d\u5fc3\u3002 10. \u7535\u7f51\u8001\u5316\u4e25\u91cd\uff1a\u7f8e\u56fd\u7535\u7f51\u8bbe\u65bd\u5e73\u5747\u5df2\u4f7f\u752840\u5e74\uff0c2030\u5e74\u7f8e\u56fd\u6570\u636e\u4e2d\u5fc3\u9700\u6c42\u4e0e\u4f9b\u5e94\u7f3a\u53e3\u5c06\u8fbe10.4GW\u3002 11. \u80fd\u6e90\u7ed3\u6784\u9884\u6d4b\uff1a\u9ad8\u76db\u9884\u6d4b\uff0c60%\u6570\u636e\u4e2d\u5fc3\u65b0\u589e\u7535\u529b\u9700\u6c42\u5c06\u753130%\u5929\u7136\u6c14CCGT\u300130%\u5929\u7136\u6c14\u8c03\u5cf0\u7535\u5382\u300127.5%\u592a\u9633\u80fd\u300112.5%\u98ce\u80fd\u6ee1\u8db3\u3002 12. \u6838\u7535\u76ee\u6807\u8fdc\u5927\uff1a\u7f8e\u56fd\u653f\u5e9c\u63a8\u52a82050\u5e74\u6838\u7535\u5bb9\u91cf\u8fbe400GW\uff08\u5f53\u524d100GW\uff09\uff0c\u5fae\u8f6f\u7b49\u4f01\u4e1a\u901a\u8fc7\u957f\u671f\u8d2d\u7535\u534f\u8bae\u91cd\u542f\u65e7\u6838\u7535\u7ad9\u3002 13. \u8868\u540e\u4f9b\u7535\u5174\u8d77\uff1a\u201c\u81ea\u5efa\u5fae\u7535\u7f51\u3001\u76f4\u8fde\u7535\u5382\u201d\u6210\u4e3a\u7ed5\u5f00\u7535\u7f51\u74f6\u9888\u7684\u9009\u62e9\uff0c\u4f46\u5b58\u5728\u6c61\u67d3\u4e0e\u76d1\u7ba1\u4e89\u8bae\u3002 14. \u5168\u7403\u8d44\u672c\u9700\u6c42\uff1a\u52302030\u5e74\uff0c\u5168\u7403\u80fd\u6e90\u8f6c\u578b\u3001\u7535\u529b\u4e0e\u516c\u7528\u4e8b\u4e1a\u3001\u6570\u5b57\u57fa\u7840\u8bbe\u65bd\u5206\u522b\u970012\u4e07\u4ebf\u30013\u4e07\u4ebf\u30012\u4e07\u4ebf\u7f8e\u5143\u8d44\u672c\u3002 15. \u65b0\u52a0\u5761REIT\u4f18\u52bf\uff1a\u65b0\u52a0\u5761REIT\u5e02\u573a\uff08\u89c4\u6a21680\u4ebf\u7f8e\u5143\uff09\u56e0\u7a0e\u6536\u4f18\u52bf\uff0c\u6210\u4e3a\u5168\u7403\u6570\u636e\u4e2d\u5fc3REIT\u4e0a\u5e02\u70ed\u95e8\u9009\u62e9\u3002 16. \u65b0\u73a9\u5bb6\u6d8c\u5165\uff1a\u9664\u8d85\u5927\u89c4\u6a21\u4f01\u4e1a\u5916\uff0c\u65b0\u5174\u4e91\u5382\u5546\u4e5f\u5728\u65a5\u8d44\u5efa\u8bbeGPU\u6570\u636e\u4e2d\u5fc3\uff0c\u52a0\u5267\u5e02\u573a\u7ade\u4e89\u3002 17. AI\u63a8\u7406\u8017\u7535\u5de8\u5927\uff1a\u4e00\u6b21ChatGPT\u67e5\u8be2\u7684\u8017\u7535\u91cf\u7ea6\u4e3a\u4e00\u6b21Google\u641c\u7d22\u768410\u500d\uff0c\u51f8\u663eAI\u5e94\u7528\u80fd\u6548\u5dee\u5f02\u3002 18. \u94dc\u6210\u4e3a\u6218\u7565\u8d44\u6e90\uff1a\u7535\u7f51\u5927\u89c4\u6a21\u5347\u7ea7\u5c06\u63a8\u52a8\u94dc\u9700\u6c42\uff0c\u52302030\u5e74\uff0c\u7535\u7f51\u5efa\u8bbe\u5c06\u8d21\u732e\u5168\u7403\u94dc\u9700\u6c42\u589e\u957f\u768460%\u3002 19. \u5730\u7f18\u653f\u6cbb\u5de5\u5177\u5316\uff1a\u6570\u636e\u4e2d\u5fc3\u9009\u5740\u5df2\u6210\u4e3a\u5730\u7f18\u653f\u6cbb\u5de5\u5177\uff0c\u5404\u56fd\u901a\u8fc7\u653f\u7b56\u5438\u5f15\u6295\u8d44\uff0c\u62a5\u544a\u6307\u51fa\u4e2d\u56fd\u5728\u7535\u529b\u4f9b\u5e94\u65b9\u9762\u5177\u5907\u4f18\u52bf\u3002"})}function I(t={}){const{wrapper:e}={...(0,o.R)(),...t.components};return e?(0,a.jsx)(e,{...t,children:(0,a.jsx)(c,{...t})}):c(t)}}}]);